parameters.jsCode:
// Compute draft Box 1-9 style VAT return figures from raw transactions.
// Expects input item[0].json to contain { sales: [...], purchases: [...] }
// where each transaction has: amountExVat, vatAmount, vatRate, supplierVatNumber (purchases only), isEUTransaction

const data = $input.first().json;
const sales = data.sales || [];
const purchases = data.purchases || [];

const sum = (arr, field) => arr.reduce((acc, t) => acc + (Number(t[field]) || 0), 0);

const box1_outputVat = sum(sales, 'vatAmount');
const box4_inputVat = sum(purchases, 'vatAmount');
const box6_totalSalesExVat = sum(sales, 'amountExVat');
const box7_totalPurchasesExVat = sum(purchases, 'amountExVat');
const box3_totalVatDue = box1_outputVat; // simplified: no acquisitions in this template
const box5_netVatDue = box3_totalVatDue - box4_inputVat;

return [{
  json: {
    period: { start: $env.VAT_PERIOD_START, end: $env.VAT_PERIOD_END },
    box1_vatDueOnSales: Number(box1_outputVat.toFixed(2)),
    box3_totalVatDue: Number(box3_totalVatDue.toFixed(2)),
    box4_vatReclaimedOnPurchases: Number(box4_inputVat.toFixed(2)),
    box5_netVatDue: Number(box5_netVatDue.toFixed(2)),
    box6_totalSalesExVat: Number(box6_totalSalesExVat.toFixed(2)),
    box7_totalPurchasesExVat: Number(box7_totalPurchasesExVat.toFixed(2)),
    salesCount: sales.length,
    purchasesCount: purchases.length,
    rawSales: sales,
    rawPurchases: purchases
  }
}];

// Flag anomalies that need human review before submission.
const LARGE_TXN_THRESHOLD = Number($env.LARGE_TRANSACTION_THRESHOLD || 10000);
const VAT_NUMBER_CHECK_THRESHOLD = Number($env.VAT_NUMBER_CHECK_THRESHOLD || 135);

const input = $input.first().json;
const anomalies = [];

for (const t of input.rawSales) {
  if (Math.abs(Number(t.amountExVat)) >= LARGE_TXN_THRESHOLD) {
    anomalies.push(`Large sales transaction: ${t.description || t.id} (£${t.amountExVat})`);
  }
}

for (const t of input.rawPurchases) {
  if (Math.abs(Number(t.amountExVat)) >= LARGE_TXN_THRESHOLD) {
    anomalies.push(`Large purchase transaction: ${t.description || t.id} (£${t.amountExVat})`);
  }
  if (Number(t.vatAmount) < 0) {
    anomalies.push(`Negative VAT amount on purchase: ${t.description || t.id}`);
  }
  if (Number(t.amountExVat) >= VAT_NUMBER_CHECK_THRESHOLD && !t.supplierVatNumber) {
    anomalies.push(`Purchase above £${VAT_NUMBER_CHECK_THRESHOLD} missing supplier VAT number: ${t.description || t.id}`);
  }
}

return [{
  json: {
    ...input,
    anomalyCount: anomalies.length,
    anomalies
  }
}];

